export * from "@hooks/use-data-grid";
export * from "@lib/data-grid";
export * from "@lib/data-grid-types";
export * from "./data-grid";
export * from "./data-grid-cell";
export * from "./data-grid-cell-variants";
export * from "./data-grid-cell-wrapper";
export * from "./data-grid-column-header";
export * from "./data-grid-context-menu";
export * from "./data-grid-keyboard-shortcuts";
export * from "./data-grid-paste-dialog";
export * from "./data-grid-row";
export * from "./data-grid-search";

/* biome-ignore-all lint/a11y/useSemanticElements: Virtualized ARIA grid uses div roles to support spreadsheet navigation, pinned columns, and measured rows. */
"use client";
import * as React from "react";
import { useAsRef } from "@hooks/use-as-ref";
import type { useDataGrid } from "@hooks/use-data-grid";
import { flexRender, getColumnBorderVisibility, getColumnPinningStyle, } from "@lib/data-grid";
import type { Direction } from "@lib/data-grid-types";
import { cn } from "@lib/utils";
import { createIconSlot } from "@lib/icon-context";
import { DataGridColumnHeader } from "./data-grid-column-header";
import { DataGridContextMenu } from "./data-grid-context-menu";
import { DataGridPasteDialog } from "./data-grid-paste-dialog";
import { DataGridRow } from "./data-grid-row";
import { DataGridSearch } from "./data-grid-search";
const EMPTY_CELL_SELECTION_SET = new Set<string>();
const Plus = createIconSlot("plus");
interface DataGridProps<TData> extends Omit<ReturnType<typeof useDataGrid<TData>>, "dir">, Omit<React.ComponentProps<"div">, "contextMenu"> {
    dir?: Direction;
    height?: number;
    stretchColumns?: boolean;
}
export function DataGrid<TData>({ dataGridRef, headerRef, rowMapRef, footerRef, dir = "ltr", table, tableMeta, virtualTotalSize, virtualItems, measureElement, columns, columnSizeVars, searchState, searchMatchesByRow, activeSearchMatch, cellSelectionMap, focusedCell, editingCell, rowHeight, contextMenu, pasteDialog, onRowAdd: onRowAddProp, height = 600, stretchColumns = false, adjustLayout = false, className, ...props }: DataGridProps<TData>) {
    const rows = table.getRowModel().rows;
    const readOnly = tableMeta?.readOnly ?? false;
    const columnVisibility = table.getState().columnVisibility;
    const columnPinning = table.getState().columnPinning;
    const onRowAddRef = useAsRef(onRowAddProp);
    const onRowAdd = React.useCallback((event: React.MouseEvent<HTMLDivElement>) => {
        onRowAddRef.current?.(event);
    }, [onRowAddRef]);
    const onDataGridContextMenu = React.useCallback((event: React.MouseEvent<HTMLDivElement>) => {
        event.preventDefault();
    }, []);
    const onFooterCellKeyDown = React.useCallback((event: React.KeyboardEvent<HTMLDivElement>) => {
        if (!onRowAddRef.current)
            return;
        if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            onRowAddRef.current();
        }
    }, [onRowAddRef]);
    return (<div data-slot="grid-wrapper" dir={dir} {...props} className={cn("relative flex w-full flex-col", className)}>
      {searchState && <DataGridSearch {...searchState}/>}
      <DataGridContextMenu tableMeta={tableMeta} columns={columns} contextMenu={contextMenu}/>
      <DataGridPasteDialog tableMeta={tableMeta} pasteDialog={pasteDialog}/>
      <div role="grid" aria-label="Data grid" aria-rowcount={rows.length + (onRowAddProp ? 1 : 0)} aria-colcount={columns.length} data-slot="grid" tabIndex={0} ref={dataGridRef} className={cn("relative grid select-none overflow-auto border border-border bg-surface-floating focus:outline-none focus-visible:ring-1 focus-visible:ring-focus-ring", "rounded-xl")} style={{
            ...columnSizeVars,
            maxHeight: `${height}px`,
        }} onContextMenu={onDataGridContextMenu}>
        <div role="rowgroup" data-slot="grid-header" ref={headerRef} className="sticky top-0 z-raised grid border-b border-border bg-surface-floating">
          {table.getHeaderGroups().map((headerGroup, rowIndex) => (<div key={headerGroup.id} role="row" aria-rowindex={rowIndex + 1} data-slot="grid-header-row" tabIndex={-1} className="flex w-full">
              {headerGroup.headers.map((header, colIndex) => {
                const sorting = table.getState().sorting;
                const currentSort = sorting.find((sort) => sort.id === header.column.id);
                const isSortable = header.column.getCanSort();
                const nextHeader = headerGroup.headers[colIndex + 1];
                const isLastColumn = colIndex === headerGroup.headers.length - 1;
                const { showEndBorder, showStartBorder } = getColumnBorderVisibility({
                    column: header.column,
                    nextColumn: nextHeader?.column,
                    isLastColumn,
                });
                return (<div key={header.id} role="columnheader" aria-colindex={colIndex + 1} aria-sort={currentSort?.desc === false
                        ? "ascending"
                        : currentSort?.desc === true
                            ? "descending"
                            : isSortable
                                ? "none"
                                : undefined} data-slot="grid-header-cell" tabIndex={-1} className={cn("relative", {
                        grow: stretchColumns && header.column.id !== "select",
                        "border-e border-border": showEndBorder && header.column.id !== "select",
                        "border-s border-border": showStartBorder && header.column.id !== "select",
                    })} style={{
                        ...getColumnPinningStyle({ column: header.column, dir }),
                        width: `calc(var(--header-${header.id}-size) * 1px)`,
                    }}>
                    {header.isPlaceholder ? null : typeof header.column
                        .columnDef.header === "function" ? (<div className="size-full px-3 py-1.5">
                        {flexRender(header.column.columnDef.header, header.getContext())}
                      </div>) : (<DataGridColumnHeader header={header} table={table}/>)}
                  </div>);
            })}
            </div>))}
        </div>
        <div role="rowgroup" data-slot="grid-body" className="relative grid" style={{
            height: `${virtualTotalSize}px`,
            contain: adjustLayout ? "layout paint" : "strict",
        }}>
          {virtualItems.map((virtualItem) => {
            const row = rows[virtualItem.index];
            if (!row)
                return null;
            const cellSelectionKeys = cellSelectionMap?.get(virtualItem.index) ??
                EMPTY_CELL_SELECTION_SET;
            const searchMatchColumns = searchMatchesByRow?.get(virtualItem.index) ?? null;
            const isActiveSearchRow = activeSearchMatch?.rowIndex === virtualItem.index;
            return (<DataGridRow key={row.id} row={row} tableMeta={tableMeta} rowMapRef={rowMapRef} virtualItem={virtualItem} measureElement={measureElement} rowHeight={rowHeight} columnVisibility={columnVisibility} columnPinning={columnPinning} focusedCell={focusedCell} editingCell={editingCell} cellSelectionKeys={cellSelectionKeys} searchMatchColumns={searchMatchColumns} activeSearchMatch={isActiveSearchRow ? activeSearchMatch : null} dir={dir} adjustLayout={adjustLayout} stretchColumns={stretchColumns} readOnly={readOnly}/>);
        })}
        </div>
        {!readOnly && onRowAdd && (<div role="rowgroup" data-slot="grid-footer" ref={footerRef} className="sticky bottom-0 z-raised grid border-t border-border bg-surface-floating">
            <div role="row" aria-rowindex={rows.length + 2} data-slot="grid-add-row" tabIndex={-1} className="flex w-full">
              <div role="gridcell" tabIndex={0} className="relative flex h-control-sm grow items-center bg-transparent transition-colors duration-fast hover:bg-hover focus:bg-active focus:outline-none" style={{
                width: table.getTotalSize(),
                minWidth: table.getTotalSize(),
            }} onClick={onRowAdd} onKeyDown={onFooterCellKeyDown}>
                <div className="sticky start-0 flex items-center gap-2 px-3 text-fg-muted">
                  <Plus className="size-3.5"/>
                  <span className="text-body">Add row</span>
                </div>
              </div>
            </div>
          </div>)}
      </div>
    </div>);
}

/* biome-ignore-all lint/a11y/useSemanticElements: Virtualized ARIA grid rows and cells must remain divs for measured layout and pinned column positioning. */
"use client";
import type { ColumnPinningState, Row, TableMeta, VisibilityState, } from "@tanstack/react-table";
import type { VirtualItem } from "@tanstack/react-virtual";
import * as React from "react";
import { useComposedRefs } from "@lib/compose-refs";
import { flexRender, getCellKey, getColumnBorderVisibility, getColumnPinningStyle, getRowHeightValue, } from "@lib/data-grid";
import type { CellPosition, Direction, RowHeightValue, } from "@lib/data-grid-types";
import { cn } from "@lib/utils";
import { DataGridCell } from "./data-grid-cell";
interface DataGridRowProps<TData> extends React.ComponentProps<"div"> {
    row: Row<TData>;
    tableMeta: TableMeta<TData>;
    virtualItem: VirtualItem;
    measureElement: (node: Element | null) => void;
    rowMapRef: React.RefObject<Map<number, HTMLDivElement>>;
    rowHeight: RowHeightValue;
    columnVisibility: VisibilityState;
    columnPinning: ColumnPinningState;
    focusedCell: CellPosition | null;
    editingCell: CellPosition | null;
    cellSelectionKeys: Set<string>;
    searchMatchColumns: Set<string> | null;
    activeSearchMatch: CellPosition | null;
    dir: Direction;
    readOnly: boolean;
    stretchColumns: boolean;
    adjustLayout: boolean;
}
export const DataGridRow = React.memo(DataGridRowImpl, (prev, next) => {
    const prevRowIndex = prev.virtualItem.index;
    const nextRowIndex = next.virtualItem.index;
    // Re-render if row identity changed
    if (prev.row.id !== next.row.id) {
        return false;
    }
    // Re-render if row data (original) reference changed
    if (prev.row.original !== next.row.original) {
        return false;
    }
    // Re-render if virtual position changed (handles transform updates)
    if (prev.virtualItem.start !== next.virtualItem.start) {
        return false;
    }
    // Re-render if focus state changed for this row
    const prevHasFocus = prev.focusedCell?.rowIndex === prevRowIndex;
    const nextHasFocus = next.focusedCell?.rowIndex === nextRowIndex;
    if (prevHasFocus !== nextHasFocus) {
        return false;
    }
    // Re-render if focused column changed within this row
    if (nextHasFocus && prevHasFocus) {
        if (prev.focusedCell?.columnId !== next.focusedCell?.columnId) {
            return false;
        }
    }
    // Re-render if editing state changed for this row
    const prevHasEditing = prev.editingCell?.rowIndex === prevRowIndex;
    const nextHasEditing = next.editingCell?.rowIndex === nextRowIndex;
    if (prevHasEditing !== nextHasEditing) {
        return false;
    }
    // Re-render if editing column changed within this row
    if (nextHasEditing && prevHasEditing) {
        if (prev.editingCell?.columnId !== next.editingCell?.columnId) {
            return false;
        }
    }
    // Re-render if this row's selected cells changed
    // Using stable Set reference that only includes this row's cells
    if (prev.cellSelectionKeys !== next.cellSelectionKeys) {
        return false;
    }
    // Re-render if column visibility changed
    if (prev.columnVisibility !== next.columnVisibility) {
        return false;
    }
    // Re-render if row height changed
    if (prev.rowHeight !== next.rowHeight) {
        return false;
    }
    // Re-render if column pinning state changed
    if (prev.columnPinning !== next.columnPinning) {
        return false;
    }
    // Re-render if readOnly changed
    if (prev.readOnly !== next.readOnly) {
        return false;
    }
    // Re-render if search match columns changed for this row
    if (prev.searchMatchColumns !== next.searchMatchColumns) {
        return false;
    }
    // Re-render if active search match changed for this row
    if (prev.activeSearchMatch?.columnId !== next.activeSearchMatch?.columnId) {
        return false;
    }
    // Re-render if direction changed
    if (prev.dir !== next.dir) {
        return false;
    }
    // Re-render if adjustLayout state changed
    if (prev.adjustLayout !== next.adjustLayout) {
        return false;
    }
    // Re-render if stretchColumns changed
    if (prev.stretchColumns !== next.stretchColumns) {
        return false;
    }
    // Skip re-render - props are equal
    return true;
}) as typeof DataGridRowImpl;
function DataGridRowImpl<TData>({ row, tableMeta, virtualItem, measureElement, rowMapRef, rowHeight, columnVisibility, columnPinning, focusedCell, editingCell, cellSelectionKeys, searchMatchColumns, activeSearchMatch, dir, readOnly, stretchColumns, adjustLayout, className, style, ref, ...props }: DataGridRowProps<TData>) {
    const virtualRowIndex = virtualItem.index;
    const onRowChange = React.useCallback((node: HTMLDivElement | null) => {
        if (typeof virtualRowIndex === "undefined")
            return;
        if (node) {
            measureElement(node);
            rowMapRef.current?.set(virtualRowIndex, node);
        }
        else {
            rowMapRef.current?.delete(virtualRowIndex);
        }
    }, [virtualRowIndex, measureElement, rowMapRef]);
    const rowRef = useComposedRefs(ref, onRowChange);
    const isRowSelected = row.getIsSelected();
    // Memoize visible cells to avoid recreating cell array on every render
    // Though TanStack returns new Cell wrappers, memoizing the array helps React's reconciliation
    // biome-ignore lint/correctness/useExhaustiveDependencies: columnVisibility and columnPinning are used for calculating the visible cells
    const visibleCells = React.useMemo(() => row.getVisibleCells(), [row, columnVisibility, columnPinning]);
    return (<div key={row.id} role="row" aria-rowindex={virtualRowIndex + 2} aria-selected={isRowSelected} data-index={virtualRowIndex} data-slot="grid-row" tabIndex={-1} {...props} ref={rowRef} className={cn("absolute flex w-full border-b border-border bg-surface-floating", !adjustLayout && "will-change-transform", className)} style={{
            height: `${getRowHeightValue(rowHeight)}px`,
            ...(adjustLayout
                ? { top: `${virtualItem.start}px` }
                : { transform: `translateY(${virtualItem.start}px)` }),
            ...style,
        }}>
      {visibleCells.map((cell, colIndex) => {
            const columnId = cell.column.id;
            const isCellFocused = focusedCell?.rowIndex === virtualRowIndex &&
                focusedCell?.columnId === columnId;
            const isCellEditing = editingCell?.rowIndex === virtualRowIndex &&
                editingCell?.columnId === columnId;
            const isCellSelected = cellSelectionKeys?.has(getCellKey(virtualRowIndex, columnId)) ??
                false;
            const isSearchMatch = searchMatchColumns?.has(columnId) ?? false;
            const isActiveSearchMatch = activeSearchMatch?.columnId === columnId;
            const nextCell = visibleCells[colIndex + 1];
            const isLastColumn = colIndex === visibleCells.length - 1;
            const { showEndBorder, showStartBorder } = getColumnBorderVisibility({
                column: cell.column,
                nextColumn: nextCell?.column,
                isLastColumn,
            });
            return (<div key={cell.id} role="gridcell" aria-colindex={colIndex + 1} data-highlighted={isCellFocused ? "" : undefined} data-slot="grid-cell" tabIndex={-1} className={cn({
                    grow: stretchColumns && columnId !== "select",
                    "border-e border-border": showEndBorder && columnId !== "select",
                    "border-s border-border": showStartBorder && columnId !== "select",
                })} style={{
                    ...getColumnPinningStyle({ column: cell.column, dir }),
                    width: `calc(var(--col-${columnId}-size) * 1px)`,
                }}>
            {typeof cell.column.columnDef.header === "function" ? (<div className={cn("size-full px-3 py-1.5", {
                        "bg-selection": isRowSelected,
                    })}>
                {flexRender(cell.column.columnDef.cell, cell.getContext())}
              </div>) : (<DataGridCell cell={cell} tableMeta={tableMeta} rowIndex={virtualRowIndex} columnId={columnId} rowHeight={rowHeight} isFocused={isCellFocused} isEditing={isCellEditing} isSelected={isCellSelected} isSearchMatch={isSearchMatch} isActiveSearchMatch={isActiveSearchMatch} readOnly={readOnly}/>)}
          </div>);
        })}
    </div>);
}

"use client";
import * as React from "react";
import type { DataGridCellProps } from "@lib/data-grid-types";
import { CheckboxCell, DateCell, FileCell, LongTextCell, MultiSelectCell, NumberCell, SelectCell, ShortTextCell, UrlCell, } from "./data-grid-cell-variants";
export const DataGridCell = React.memo(DataGridCellImpl, (prev, next) => {
    // Fast path: check stable primitive props first
    if (prev.isFocused !== next.isFocused)
        return false;
    if (prev.isEditing !== next.isEditing)
        return false;
    if (prev.isSelected !== next.isSelected)
        return false;
    if (prev.isSearchMatch !== next.isSearchMatch)
        return false;
    if (prev.isActiveSearchMatch !== next.isActiveSearchMatch)
        return false;
    if (prev.readOnly !== next.readOnly)
        return false;
    if (prev.rowIndex !== next.rowIndex)
        return false;
    if (prev.columnId !== next.columnId)
        return false;
    if (prev.rowHeight !== next.rowHeight)
        return false;
    // Check cell value using row.original instead of getValue() for stability
    // getValue() is unstable and recreates on every render, breaking memoization
    const prevValue = (prev.cell.row.original as Record<string, unknown>)[prev.columnId];
    const nextValue = (next.cell.row.original as Record<string, unknown>)[next.columnId];
    if (prevValue !== nextValue) {
        return false;
    }
    // Check cell/row identity
    if (prev.cell.row.id !== next.cell.row.id)
        return false;
    return true;
}) as typeof DataGridCellImpl;
function DataGridCellImpl<TData>({ cell, tableMeta, rowIndex, columnId, isFocused, isEditing, isSelected, isSearchMatch, isActiveSearchMatch, readOnly, rowHeight, }: DataGridCellProps<TData>) {
    const cellOpts = cell.column.columnDef.meta?.cell;
    const variant = cellOpts?.variant ?? "text";
    let Comp: React.ComponentType<DataGridCellProps<TData>>;
    switch (variant) {
        case "short-text":
            Comp = ShortTextCell;
            break;
        case "long-text":
            Comp = LongTextCell;
            break;
        case "number":
            Comp = NumberCell;
            break;
        case "url":
            Comp = UrlCell;
            break;
        case "checkbox":
            Comp = CheckboxCell;
            break;
        case "select":
            Comp = SelectCell;
            break;
        case "multi-select":
            Comp = MultiSelectCell;
            break;
        case "date":
            Comp = DateCell;
            break;
        case "file":
            Comp = FileCell;
            break;
        default:
            Comp = ShortTextCell;
            break;
    }
    return (<Comp cell={cell} tableMeta={tableMeta} rowIndex={rowIndex} columnId={columnId} rowHeight={rowHeight} isEditing={isEditing} isFocused={isFocused} isSelected={isSelected} isSearchMatch={isSearchMatch} isActiveSearchMatch={isActiveSearchMatch} readOnly={readOnly}/>);
}

/* biome-ignore-all lint/a11y/useSemanticElements: Grid cells use div button semantics so selection, editing, and resize interactions share one focus model. */
"use client";
import * as React from "react";
import { useComposedRefs } from "@lib/compose-refs";
import { getCellKey } from "@lib/data-grid";
import type { DataGridCellProps } from "@lib/data-grid-types";
import { cn } from "@lib/utils";
interface DataGridCellWrapperProps<TData> extends DataGridCellProps<TData>, React.ComponentProps<"div"> {
}
export function DataGridCellWrapper<TData>({ tableMeta, rowIndex, columnId, isEditing, isFocused, isSelected, isSearchMatch, isActiveSearchMatch, readOnly, rowHeight, className, onClick: onClickProp, onKeyDown: onKeyDownProp, ref, ...props }: DataGridCellWrapperProps<TData>) {
    const cellMapRef = tableMeta?.cellMapRef;
    const onCellChange = React.useCallback((node: HTMLDivElement | null) => {
        if (!cellMapRef)
            return;
        const cellKey = getCellKey(rowIndex, columnId);
        if (node) {
            cellMapRef.current.set(cellKey, node);
        }
        else {
            cellMapRef.current.delete(cellKey);
        }
    }, [rowIndex, columnId, cellMapRef]);
    const composedRef = useComposedRefs(ref, onCellChange);
    const onClick = React.useCallback((event: React.MouseEvent<HTMLDivElement>) => {
        if (!isEditing) {
            event.preventDefault();
            onClickProp?.(event);
            if (isFocused && !readOnly) {
                tableMeta?.onCellEditingStart?.(rowIndex, columnId);
            }
            else {
                tableMeta?.onCellClick?.(rowIndex, columnId, event);
            }
        }
    }, [
        tableMeta,
        rowIndex,
        columnId,
        isEditing,
        isFocused,
        readOnly,
        onClickProp,
    ]);
    const onContextMenu = React.useCallback((event: React.MouseEvent) => {
        if (!isEditing) {
            tableMeta?.onCellContextMenu?.(rowIndex, columnId, event);
        }
    }, [tableMeta, rowIndex, columnId, isEditing]);
    const onDoubleClick = React.useCallback((event: React.MouseEvent) => {
        if (!isEditing) {
            event.preventDefault();
            tableMeta?.onCellDoubleClick?.(rowIndex, columnId);
        }
    }, [tableMeta, rowIndex, columnId, isEditing]);
    const onKeyDown = React.useCallback((event: React.KeyboardEvent<HTMLDivElement>) => {
        onKeyDownProp?.(event);
        if (event.defaultPrevented)
            return;
        if (event.key === "ArrowUp" ||
            event.key === "ArrowDown" ||
            event.key === "ArrowLeft" ||
            event.key === "ArrowRight" ||
            event.key === "Home" ||
            event.key === "End" ||
            event.key === "PageUp" ||
            event.key === "PageDown" ||
            event.key === "Tab") {
            return;
        }
        if (isFocused && !isEditing && !readOnly) {
            if (event.key === "F2" || event.key === "Enter") {
                event.preventDefault();
                event.stopPropagation();
                tableMeta?.onCellEditingStart?.(rowIndex, columnId);
                return;
            }
            if (event.key === " ") {
                event.preventDefault();
                event.stopPropagation();
                tableMeta?.onCellEditingStart?.(rowIndex, columnId);
                return;
            }
            if (event.key.length === 1 && !event.ctrlKey && !event.metaKey) {
                event.preventDefault();
                event.stopPropagation();
                tableMeta?.onCellEditingStart?.(rowIndex, columnId);
            }
        }
    }, [
        onKeyDownProp,
        isFocused,
        isEditing,
        readOnly,
        tableMeta,
        rowIndex,
        columnId,
    ]);
    const onMouseDown = React.useCallback((event: React.MouseEvent) => {
        if (!isEditing) {
            tableMeta?.onCellMouseDown?.(rowIndex, columnId, event);
        }
    }, [tableMeta, rowIndex, columnId, isEditing]);
    const onMouseEnter = React.useCallback(() => {
        if (!isEditing) {
            tableMeta?.onCellMouseEnter?.(rowIndex, columnId);
        }
    }, [tableMeta, rowIndex, columnId, isEditing]);
    const onMouseUp = React.useCallback(() => {
        if (!isEditing) {
            tableMeta?.onCellMouseUp?.();
        }
    }, [tableMeta, isEditing]);
    return (<div role="button" data-slot="grid-cell-wrapper" data-editing={isEditing ? "" : undefined} data-focused={isFocused ? "" : undefined} data-selected={isSelected ? "" : undefined} tabIndex={isFocused && !isEditing ? 0 : -1} {...props} ref={composedRef} className={cn("size-full px-2 py-1.5 text-start text-body outline-none transition-colors duration-fast has-data-[slot=checkbox]:pt-2.5", {
            "ring-1 ring-inset ring-focus-ring": isFocused,
            "bg-selection": (isSearchMatch && !isActiveSearchMatch) || (isSelected && !isEditing),
            "bg-active ring-1 ring-inset ring-focus-ring": isActiveSearchMatch,
            "cursor-default": !isEditing,
            "**:data-[slot=grid-cell-content]:line-clamp-1": !isEditing && rowHeight === "short",
            "**:data-[slot=grid-cell-content]:line-clamp-2": !isEditing && rowHeight === "medium",
            "**:data-[slot=grid-cell-content]:line-clamp-3": !isEditing && rowHeight === "tall",
            "**:data-[slot=grid-cell-content]:line-clamp-4": !isEditing && rowHeight === "extra-tall",
        }, className)} onClick={onClick} onContextMenu={onContextMenu} onDoubleClick={onDoubleClick} onMouseDown={onMouseDown} onMouseEnter={onMouseEnter} onMouseUp={onMouseUp} onKeyDown={onKeyDown}/>);
}

/* biome-ignore-all lint/a11y/useSemanticElements: Editable grid cells use ARIA roles on divs to preserve spreadsheet-style focus and virtualization behavior. */
"use client";
import * as React from "react";
import { toast } from "sonner";
import { useBadgeOverflow } from "@hooks/use-badge-overflow";
import { useDebouncedCallback } from "@hooks/use-debounced-callback";
import { formatDateForDisplay, formatDateToString, formatFileSize, getCellKey, getFileIcon, getLineCount, getUrlHref, parseLocalDate, } from "@lib/data-grid";
import type { DataGridCellProps, FileCellData, } from "@lib/data-grid-types";
import { cn } from "@lib/utils";
import { createIconSlot } from "@lib/icon-context";
import { Badge } from "../badge";
import { Button } from "../button";
import { Calendar } from "./data-grid-calendar";
import { Checkbox } from "../checkbox";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList, CommandSeparator, } from "./data-grid-command";
import { Popover, PopoverAnchor, PopoverContent } from "./data-grid-popover";
import { Select, SelectContent, SelectItem, SelectTrigger, } from "../select";
import { Skeleton, Textarea } from "./data-grid-primitives";
import { DataGridCellWrapper } from "./data-grid-cell-wrapper";
const Check = createIconSlot("check");
const Upload = createIconSlot("upload");
const X = createIconSlot("x");
export function ShortTextCell<TData>({ cell, tableMeta, rowIndex, columnId, rowHeight, isEditing, isFocused, isSelected, isSearchMatch, isActiveSearchMatch, readOnly, }: DataGridCellProps<TData>) {
    const initialValue = cell.getValue() as string;
    const [value, setValue] = React.useState(initialValue);
    const cellRef = React.useRef<HTMLDivElement>(null);
    const containerRef = React.useRef<HTMLDivElement>(null);
    const prevInitialValueRef = React.useRef(initialValue);
    if (initialValue !== prevInitialValueRef.current) {
        prevInitialValueRef.current = initialValue;
