    const [value, setValue] = React.useState(initialValue ?? "");
    const containerRef = React.useRef<HTMLDivElement>(null);
    const prevInitialValueRef = React.useRef(initialValue);
    if (initialValue !== prevInitialValueRef.current) {
        prevInitialValueRef.current = initialValue;
        setValue(initialValue ?? "");
    }
    // Parse date as local time to avoid timezone shifts
    const selectedDate = value ? (parseLocalDate(value) ?? undefined) : undefined;
    const onDateSelect = React.useCallback((date: Date | undefined) => {
        if (!date || readOnly)
            return;
        // Format using local date components to avoid timezone issues
        const formattedDate = formatDateToString(date);
        setValue(formattedDate);
        tableMeta?.onDataUpdate?.({ rowIndex, columnId, value: formattedDate });
        tableMeta?.onCellEditingStop?.();
    }, [tableMeta, rowIndex, columnId, readOnly]);
    const onOpenChange = React.useCallback((open: boolean) => {
        if (open && !readOnly) {
            tableMeta?.onCellEditingStart?.(rowIndex, columnId);
        }
        else {
            tableMeta?.onCellEditingStop?.();
        }
    }, [tableMeta, rowIndex, columnId, readOnly]);
    const onWrapperKeyDown = React.useCallback((event: React.KeyboardEvent<HTMLDivElement>) => {
        if (isEditing && event.key === "Escape") {
            event.preventDefault();
            setValue(initialValue);
            tableMeta?.onCellEditingStop?.();
        }
        else if (isFocused && event.key === "Tab") {
            event.preventDefault();
            tableMeta?.onCellEditingStop?.({
                direction: event.shiftKey ? "left" : "right",
            });
        }
    }, [isEditing, isFocused, initialValue, tableMeta]);
    return (<DataGridCellWrapper<TData> ref={containerRef} cell={cell} tableMeta={tableMeta} rowIndex={rowIndex} columnId={columnId} rowHeight={rowHeight} isEditing={isEditing} isFocused={isFocused} isSelected={isSelected} isSearchMatch={isSearchMatch} isActiveSearchMatch={isActiveSearchMatch} readOnly={readOnly} onKeyDown={onWrapperKeyDown}>
      <Popover open={isEditing} onOpenChange={onOpenChange}>
        <PopoverAnchor asChild>
          <span data-slot="grid-cell-content">
            {formatDateForDisplay(value)}
          </span>
        </PopoverAnchor>
        {isEditing && (<PopoverContent data-grid-cell-editor="" align="start" alignOffset={-8} className="w-auto p-0">
            <Calendar autoFocus captionLayout="dropdown" mode="single" defaultMonth={selectedDate ?? new Date()} selected={selectedDate} onSelect={onDateSelect}/>
          </PopoverContent>)}
      </Popover>
    </DataGridCellWrapper>);
}
